+  test("reports structural errors with line and column", () => {
+    const cases = [
+      ["x\n{{else}}", "Unexpected else outside a block at line 2, column 1"],
+      ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate else at line 1, column 19"],
